49	    public <T> T merge(T originalObject, T mergingObject, Class<T> classToCast) {
50	        if (!ObjectUtils.allNotNull(originalObject, mergingObject)) {
51	            return ObjectUtils.defaultIfNull(originalObject, mergingObject);
52	        }
53	
54	        final JsonNode originJsonNode = mapper.mapper().valueToTree(originalObject);
55	        final JsonNode mergingObjectJsonNode = mapper.mapper().valueToTree(mergingObject);
56	        try {
57	            final JsonNode mergedNode = JsonMergePatch.fromJson(originJsonNode).apply(mergingObjectJsonNode);
58	            return mapper.mapper().treeToValue(mergedNode, classToCast);
59	        } catch (JsonPatchException e) {
60	            throw new InvalidRequestException(String.format(
61	                    "Couldn't create merge patch for objects with class %s", classToCast.getName()));
62	        } catch (JsonProcessingException e) {
63	            throw new InvalidRequestException(
64	                    String.format("Can't convert merging result class %s", classToCast.getName()));
65	        }
66	    }
